bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_BOT_NOT_RUNNING; exit 61; }
docker logs --tail 180 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo STK04_BOT_READY_MISSING; exit 62; }
restarts="$(docker inspect -f '{{.RestartCount}}' "$name")"
test "$restarts" -le 1 || { echo STK04_BOT_RESTART_LOOP; exit 63; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || exit 64
count="$(docker exec "$pg" sh -c 'psql -U "$POSTGRES_USER" -d videobot -tAc "SELECT count(*) FROM videobot_poll_cursor"' 2>/dev/null)" || { echo STK04_CURSOR_QUERY_FAILED; exit 65; }
test "$count" -ge 1 || { echo STK04_NO_DURABLE_RECEIVED_UPDATE; exit 66; }
echo STK04_BOT_STABLE_AND_CURSOR=PASS
packs="$(docker exec "$pg" sh -c 'psql -U "$POSTGRES_USER" -d videobot -tAc "SELECT count(*) FROM videobot_sticker_packs"' 2>/dev/null)" || exit 67
sessions="$(docker exec "$pg" sh -c 'psql -U "$POSTGRES_USER" -d videobot -tAc "SELECT count(*) FROM videobot_creator_sessions"' 2>/dev/null)" || exit 68
if test "$sessions" -gt 0;then echo STK04_EXISTING_DM_SESSION=YES;else echo STK04_EXISTING_DM_SESSION=NO;fi
if test "$packs" -gt 0;then echo STK04_EXISTING_STICKER_PACK=YES;else echo STK04_EXISTING_STICKER_PACK=NO;fi
